    if self.queue.is_empty() {
        self.queue_held = false;
    }
    let Some(saved) = item.saved else {
        return false;
    };
    if !self.in_background {
        self.sync_editing_position(cx);
    }
    self.start(item.text.to_string(), Sending::Queued(saved), cx);
