        for line in head.lines() {
            let (key, value) = line.split_once(": ")?;
            match key {
                "mode" => step.mode = SendMode::from_key(value.trim())?,
                "model" => step.model = Some(value.trim().to_string()),
                "effort" => step.effort = Some(value.trim().to_string()),
                _ => {}
            }
        }
        Some(step)
    }
