    fn render_sidebar(
        &self,
        closing: Option<&RefsClosing>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let tab = closing.map_or_else(|| self.sidebar_shown_tab(), |closing| closing.tab);
        if tab != SidebarTab::Tasks {
