                        subagents_scroll: &self.subagents_scroll,
                        understanding_scroll: &self.understanding_scroll,
                        heights: &self.refs_panels,
                    },
                    self.file_opener(cx),
                    cx,
                )
            }
            SidebarTab::Tasks => self.render_tasks_tab(window, cx),
        };
