impl HistoryList {
    fn new(
        ids: (&'static str, &'static str, &'static str),
        (singular, plural, back): (&'static str, &'static str, &'static str),
        id_base: usize,
        collapse_steps: bool,
        selectable: bool,
        by_session: bool,
    ) -> Self {
        Self {
            toggle: ids.0,
            list: ids.1,
            item: ids.2,
            singular,
            plural,
            back,
            id_base,
            expanded: false,
            open: None,
            rows: MeasuredList::new(task_table::OVERDRAW),
            laid_out: RefCell::default(),
            opened: 0,
            scroll_to_latest: Cell::new(false),
            collapse_steps,
