async fn previous_tasks_can_be_selected_and_sent_to_the_other_mode(cx: &mut TestAppContext) {
    use crate::chat_input::SendMode;
    let dir = std::env::temp_dir().join(format!("suspense-batch-{}", std::process::id()));
