        Some(SendMode::Code),
        Some(SendMode::Both),
        Some(SendMode::Spec),
        Some(SendMode::Code),
        None,
        Some(SendMode::Spec),
        Some(SendMode::Code),
    ];
    prompt_mode.update(cx, |this, cx| {
        for mode in modes {
            let ix = this.push_task(format!("Task {}", this.tasks.len()).into(), cx);
            this.tasks[ix].sent = super::SentAs {
                mode,
                attached_text: vec!["note".into()],
